    # Calls:
    # 1 - (200) POST:/api/v1/admin/analytics/snapshot
    # 2 - (200) PATCH:/api/v1/users/{id}
    # 3 - (200) POST:/api/v1/admin/analytics/snapshot
    # Found 1 potential fault of type-code 970
    @timeout_decorator.timeout(60)
    def test_11_post_on_snapshot_stillAllowedAfterPermissionRevoked(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"victim\", " + \
            " \"password\" : \"Thesis-Pass-1234\" " + \
            " } "
        res_victim = requests \
                .post("http://localhost:8212/api/v1/auth/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_victim =  res_victim.json()["access_token"]
        
        auth_victim = "Bearer " + token_victim
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"admin\", " + \
            " \"password\" : \"Thesis-Pass-1234\" " + \
            " } "
        res_operator = requests \
                .post("http://localhost:8212/api/v1/auth/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_operator =  res_operator.json()["access_token"]
        
        auth_operator = "Bearer " + token_operator
        
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/v1/admin/analytics/snapshot",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        location_snapshot__2 = res_0.headers['location']
        assert is_valid_uri_or_empty(location_snapshot__2)
        
        assert res_0.status_code == 200
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["snapshot_date"] == "2026-10-15"
        assert res_0.json()["total_repositories"] == 0
        assert res_0.json()["total_artifacts"] == 0
        assert res_0.json()["total_storage_bytes"] == 0
        assert res_0.json()["total_downloads"] == 0
        assert res_0.json()["total_users"] == 6
        
        headers = {}
        headers["Authorization"] = auth_operator # operator
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"is_admin\" : false " + \
            " } "
        headers['Accept'] = "application/json"
        res_1 = requests \
                .patch(self.baseUrlOfSut + "/api/v1/users/449c4f42-e5ed-4a48-8166-17e7f58f9b3a",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert res_1.json()["username"] == "victim"
        assert res_1.json()["email"] == "victim@probe.test"
        assert res_1.json()["display_name"] is None
        assert res_1.json()["auth_provider"] == "local"
        assert res_1.json()["is_active"] == True
        assert res_1.json()["is_admin"] == False
        assert res_1.json()["must_change_password"] == False
        assert res_1.json()["last_login_at"] == "2026-10-15T05:36:20.343969Z"
        assert res_1.json()["created_at"] == "2026-10-15T05:01:19.087294Z"
        
        # Fault970. Stateful Authorization: privilege persists after a permission-reducing transition.
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_2 = requests \
                .post(self.baseUrlOfSut + "/api/v1/admin/analytics/snapshot",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        location_snapshot__31 = res_2.headers['location']
        assert is_valid_uri_or_empty(location_snapshot__31)
        
        assert res_2.status_code == 200
        assert "application/json" in res_2.headers["content-type"]
        assert res_2.json()["snapshot_date"] == "2026-10-15"
        assert res_2.json()["total_repositories"] == 0
        assert res_2.json()["total_artifacts"] == 0
        assert res_2.json()["total_storage_bytes"] == 0
        assert res_2.json()["total_downloads"] == 0
        assert res_2.json()["total_users"] == 6
        
        # Cleanup actions
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "*/*"
        res_3 = requests \
                .delete(resolve_location(location_snapshot__2, self.baseUrlOfSut + str("/api/v1/admin/telemetry/crashes/L15d1InN3")),
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_3.status_code == 400
        assert "text/plain" in res_3.headers["content-type"]
        assert "Invalid URL: UUID parsing failed: invalid character: found `L` at 1" in res_3.text
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "*/*"
        res_4 = requests \
                .delete(resolve_location(location_snapshot__31, self.baseUrlOfSut + str("/api/v1/admin/telemetry/crashes/M_s")),
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_4.status_code == 400
        assert "text/plain" in res_4.headers["content-type"]
        assert "Invalid URL: UUID parsing failed: invalid character: found `M` at 1" in res_4.text
    
    
